import{_ as o,a as n,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 全册语法总结 · 过去完成时至现在完成时与将来时被动","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第一册：英语初阶 · 全册语法总结 · 过去完成时至现在完成时与将来时被动","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-1/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册语法总结 · had better 与时间表达至过去进行时","link":"/life/english/new-concept/book-1/grammar-part-05"},"next":{"text":"第一册：英语初阶 · 全册单词总结","link":"/life/english/new-concept/book-1/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册语法总结 · had better 与时间表达至过去进行时","link":"/life/english/new-concept/book-1/grammar-part-05"},"next":{"text":"第一册：英语初阶 · 全册单词总结","link":"/life/english/new-concept/book-1/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-1/grammar-part-06.md","filePath":"life/english/new-concept/book-1/grammar-part-06.md"}'),s={name:"life/english/new-concept/book-1/grammar-part-06.md"};function i(r,e,h,l,p,d){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-全册语法总结-·-过去完成时至现在完成时与将来时被动" tabindex="-1">第一册：英语初阶 · 全册语法总结 · 过去完成时至现在完成时与将来时被动 <a class="header-anchor" href="#第一册-英语初阶-·-全册语法总结-·-过去完成时至现在完成时与将来时被动" aria-label="Permalink to &quot;第一册：英语初阶 · 全册语法总结 · 过去完成时至现在完成时与将来时被动&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="过去完成时" tabindex="-1">过去完成时 <a class="header-anchor" href="#过去完成时" aria-label="Permalink to &quot;过去完成时 {#过去完成时}&quot;">​</a></h2><p>过去完成时由 had + 过去分词构成，表示相对于一个过去参照点更早发生的动作。需要有过去参照点，不能只因为动作很久以前就用 had done。By the time we arrived, the shop had closed 中到达是参照点，关门更早。时间顺序非常明确时一般过去时也可能足够，但本课用过去完成时突出先后。</p><p><strong>L119 原创例句：</strong> By the time we arrived, the museum had closed.</p><p>我们到达时，博物馆已经关门了。</p><p><strong>L120 原创例句：</strong> She had saved the file before the computer stopped.</p><p>电脑停止运行前她已经保存了文件。</p><p><strong>易错：</strong> 过去完成时必须相对于过去参照点；不要只因 yesterday 就任意加 had。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-119">Lesson 119</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-120">Lesson 120</a></p><h2 id="关系代词作主语" tabindex="-1">关系代词作主语 <a class="header-anchor" href="#关系代词作主语" aria-label="Permalink to &quot;关系代词作主语 {#关系代词作主语}&quot;">​</a></h2><p>定语从句用来修饰前面的名词。指人可用 who，指物可用 which，限制性从句中常可用 that。关系代词在从句中作主语时不能省略，也不能再重复 he/it 等主语。先找先行词，再确定从句缺什么成分，不能只看到中文“的”就机械插入 who。介词短语 in a hat 也可直接修饰人。</p><p><strong>L121 原创例句：</strong> The woman who lives upstairs is a violinist.</p><p>住楼上的那位女士是小提琴手。</p><p><strong>L122 原创例句：</strong> The lamp that stands by the sofa is broken.</p><p>沙发旁那盏灯坏了。</p><p><strong>易错：</strong> 不能写 the woman who she lives upstairs；who 已经是从句主语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-121">Lesson 121</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-122">Lesson 122</a></p><h2 id="关系代词作宾语" tabindex="-1">关系代词作宾语 <a class="header-anchor" href="#关系代词作宾语" aria-label="Permalink to &quot;关系代词作宾语 {#关系代词作宾语}&quot;">​</a></h2><p>在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p><p><strong>L123 原创例句：</strong> The guide we met in Perth spoke three languages.</p><p>我们在珀斯遇到的导游会说三种语言。</p><p><strong>L124 原创例句：</strong> This is the photograph that I took at the harbour.</p><p>这是我在港口拍的照片。</p><p><strong>易错：</strong> met 后不再补 him；先行词 guide 已通过关系从句充当 met 的宾语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-123">Lesson 123</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-124">Lesson 124</a></p><h2 id="have-to-的时态与否定" tabindex="-1">have to 的时态与否定 <a class="header-anchor" href="#have-to-的时态与否定" aria-label="Permalink to &quot;have to 的时态与否定 {#have-to-的时态与否定}&quot;">​</a></h2><p>have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p><p><strong>L125 原创例句：</strong> I had to water the plants before work.</p><p>上班前我不得不给植物浇水。</p><p><strong>L126 原创例句：</strong> She does not have to work this Sunday.</p><p>她这周日不必工作。</p><p><strong>易错：</strong> doesn&#39;t 后接 have to 而非 has to；否定 have to 表不必。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-125">Lesson 125</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-126">Lesson 126</a></p><h2 id="must-cannot-表现在推断" tabindex="-1">must/cannot 表现在推断 <a class="header-anchor" href="#must-cannot-表现在推断" aria-label="Permalink to &quot;must/cannot 表现在推断 {#must-cannot-表现在推断}&quot;">​</a></h2><p>must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p><p><strong>L127 原创例句：</strong> The office lights are on; someone must be inside.</p><p>办公室灯亮着，里面一定有人。</p><p><strong>L128 原创例句：</strong> That cannot be our bus; it has a different number.</p><p>那不可能是我们的公交车，它的编号不同。</p><p><strong>易错：</strong> mustn&#39;t be 表禁止时不等于不可能；推断不可能常用 can&#39;t be。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-127">Lesson 127</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-128">Lesson 128</a></p><h2 id="情态动词-have-done" tabindex="-1">情态动词 + have done <a class="header-anchor" href="#情态动词-have-done" aria-label="Permalink to &quot;情态动词 + have done {#情态动词-have-done}&quot;">​</a></h2><p>must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p><p><strong>L129 原创例句：</strong> The road is wet; it must have rained overnight.</p><p>路是湿的，夜里一定下过雨。</p><p><strong>L130 原创例句：</strong> He cannot have read the sign; it was covered.</p><p>他不可能读到标志，它被遮住了。</p><p><strong>易错：</strong> must have rained 是推测，不能写 must had rained；情态动词后保留 have 原形。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-129">Lesson 129</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-130">Lesson 130</a></p><h2 id="may-might-的时间层次" tabindex="-1">may/might 的时间层次 <a class="header-anchor" href="#may-might-的时间层次" aria-label="Permalink to &quot;may/might 的时间层次 {#may-might-的时间层次}&quot;">​</a></h2><p>may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p><p><strong>L131 原创例句：</strong> The parcel may arrive tomorrow.</p><p>包裹可能明天到。</p><p><strong>L132 原创例句：</strong> Ella might have left her phone on the train.</p><p>埃拉可能把手机落在火车上了。</p><p><strong>易错：</strong> may not arrive 表可能不到，不是“不可能到”；不要夸大确定程度。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-131">Lesson 131</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-132">Lesson 132</a></p><h2 id="间接引语的时态回移" tabindex="-1">间接引语的时态回移 <a class="header-anchor" href="#间接引语的时态回移" aria-label="Permalink to &quot;间接引语的时态回移 {#间接引语的时态回移}&quot;">​</a></h2><p>过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p><p><strong>L133 原创例句：</strong> The reporter said that the bridge was closed.</p><p>记者说那座桥关闭了。</p><p><strong>L134 原创例句：</strong> Maya told us that she was studying abroad.</p><p>玛雅告诉我们她正在国外学习。</p><p><strong>易错：</strong> told that 通常缺少听话者；用 told us that 或 said that。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-133">Lesson 133</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-134">Lesson 134</a></p><h2 id="would-与-had-done-的回移" tabindex="-1">would 与 had done 的回移 <a class="header-anchor" href="#would-与-had-done-的回移" aria-label="Permalink to &quot;would 与 had done 的回移 {#would-与-had-done-的回移}&quot;">​</a></h2><p>在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p><p><strong>L135 原创例句：</strong> He said he would send the document the next day.</p><p>他说他将在第二天发送文件。</p><p><strong>L136 原创例句：</strong> She told me she had finished the repairs.</p><p>她告诉我她已经修好了。</p><p><strong>易错：</strong> would 后用 send 原形；had 后用 finished 分词，两种形式不要互换。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-135">Lesson 135</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-136">Lesson 136</a></p><h2 id="真实条件句" tabindex="-1">真实条件句 <a class="header-anchor" href="#真实条件句" aria-label="Permalink to &quot;真实条件句 {#真实条件句}&quot;">​</a></h2><p>表达未来可能实现的条件时，常用 if + 一般现在时，主句 will + 原形。if 从句不是已经发生，而是条件；主句也不是绝对保证，而是条件成立时的结果。从句放前面通常用逗号分隔，放后面通常不需要。不要因条件指未来就在普通 if 条件从句中机械加 will。</p><p><strong>L137 原创例句：</strong> If we finish early, we will take a walk.</p><p>如果我们早点完成，就会去散步。</p><p><strong>L138 原创例句：</strong> We will stay indoors if it rains tomorrow.</p><p>如果明天下雨，我们就待在室内。</p><p><strong>易错：</strong> 本课普通未来条件用 if it rains，而非 if it will rain。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-137">Lesson 137</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-138">Lesson 138</a></p><h2 id="间接疑问句的陈述语序" tabindex="-1">间接疑问句的陈述语序 <a class="header-anchor" href="#间接疑问句的陈述语序" aria-label="Permalink to &quot;间接疑问句的陈述语序 {#间接疑问句的陈述语序}&quot;">​</a></h2><p>宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p><p><strong>L139 原创例句：</strong> She wants to know whether the office is open.</p><p>她想知道办公室是否开门。</p><p><strong>L140 原创例句：</strong> Could you tell me when the meeting starts?</p><p>你能告诉我会议什么时候开始吗？</p><p><strong>易错：</strong> 从句写 when the meeting starts，不写 when does the meeting start。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-139">Lesson 139</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-140">Lesson 140</a></p><h2 id="一般过去时被动语态" tabindex="-1">一般过去时被动语态 <a class="header-anchor" href="#一般过去时被动语态" aria-label="Permalink to &quot;一般过去时被动语态 {#一般过去时被动语态}&quot;">​</a></h2><p>被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p><p><strong>L141 原创例句：</strong> The guests were invited by email.</p><p>客人们是通过电子邮件受邀的。</p><p><strong>L142 原创例句：</strong> This bridge was built fifty years ago.</p><p>这座桥建于五十年前。</p><p><strong>易错：</strong> by email 表方式，不是执行者；被动中的 built 是分词，不是 build 原形。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-141">Lesson 141</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-142">Lesson 142</a></p><h2 id="现在完成时与将来时被动" tabindex="-1">现在完成时与将来时被动 <a class="header-anchor" href="#现在完成时与将来时被动" aria-label="Permalink to &quot;现在完成时与将来时被动 {#现在完成时与将来时被动}&quot;">​</a></h2><p>现在完成时被动为 have/has been + 过去分词，将来时被动为 will be + 过去分词。have/has 仍要与主语一致，been 不可漏；will 后用原形 be，不用 been。先判断是否被动，再判断完成或将来，不能把两种结构拼成 will been。表达“树木已被种下”与“明天将被种下”时，动作对象相同而时间不同。</p><p><strong>L143 原创例句：</strong> The path has been cleared of fallen branches.</p><p>小路上的落枝已经被清理了。</p><p><strong>L144 原创例句：</strong> New trees will be planted beside the stream.</p><p>小溪旁将种上新树。</p><p><strong>易错：</strong> has been cleared 不能省略 been；will be planted 中 be 不写成 been。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-143">Lesson 143</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-144">Lesson 144</a></p>',107)])])}const f=o(s,[["render",i]]);export{c as __pageData,f as default};
